import inspect
import re
from solution import neg_nos


def _parse_numbers(text):
    """Parse printed numbers into a list."""
    tokens = re.findall(r"-?\d+(?:\.\d+)?", text)
    out = []
    for t in tokens:
        if "." in t:
            out.append(float(t))
        else:
            out.append(int(t))
    return out


def _observed(values, capsys):
    """Return negatives via return value if present else via printed output."""
    ret = neg_nos(values)
    out = capsys.readouterr().out
    if isinstance(ret, (list, tuple)):
        return list(ret)
    if ret is None:
        return _parse_numbers(out)
    if isinstance(ret, str):
        return _parse_numbers(ret)
    if isinstance(ret, (int, float)):
        return [ret]
    try:
        return list(ret)
    except Exception:
        return _parse_numbers(out)


def test_issue_example(capsys):
    """Example: neg_nos([-1,4,5,-6]) == -1,-6."""
    result = _observed([-1, 4, 5, -6], capsys)
    expected = [-1, -6]  # -1<0 keep; 4>=0 drop; 5>=0 drop; -6<0 keep
    assert result == expected


def test_issue_all_negative(capsys):
    """Print negative numbers in a list."""
    result = _observed([-3, -1, -2], capsys)
    expected = [-3, -1, -2]  # -3<0 keep; -1<0 keep; -2<0 keep
    assert result == expected


def test_issue_all_positive_empty(capsys):
    """Print negative numbers in a list with no negatives gives empty."""
    result = _observed([1, 2, 3], capsys)
    expected = []  # 1>=0 drop; 2>=0 drop; 3>=0 drop
    assert result == expected


def test_issue_empty_input(capsys):
    """Empty list gives empty result."""
    result = _observed([], capsys)
    expected = []  # no elements so nothing to keep
    assert result == expected


def test_issue_zero_not_negative(capsys):
    """Zero is not negative and must not be printed."""
    result = _observed([0, -1, 0, 2], capsys)
    expected = [-1]  # 0>=0 drop; -1<0 keep; 0>=0 drop; 2>=0 drop
    assert result == expected


def test_issue_single_negative(capsys):
    """Single negative list returns that element."""
    result = _observed([-5], capsys)
    expected = [-5]  # -5<0 keep
    assert result == expected


def test_issue_float_negatives(capsys):
    """Negative floats count as negative numbers."""
    result = _observed([-1.5, 2.5, -0.2, 0.0], capsys)
    expected = [-1.5, -0.2]  # -1.5<0 keep; 2.5>=0 drop; -0.2<0 keep; 0.0>=0 drop
    assert result == expected


def test_issue_order_preserved(capsys):
    """Negatives keep original order."""
    result = _observed([5, -3, 4, -1, -2], capsys)
    expected = [-3, -1, -2]  # 5 drop; -3 keep 1st; 4 drop; -1 keep 2nd; -2 keep 3rd
    assert result == expected


def test_issue_duplicates_kept(capsys):
    """Duplicate negatives are all printed."""
    result = _observed([-2, 3, -2, 0, -1], capsys)
    expected = [-2, -2, -1]  # -2 keep; 3 drop; -2 keep again; 0 drop; -1 keep
    assert result == expected


def test_contract_input_not_mutated(capsys):
    """Implement neg_nos(list1) must not mutate the input list."""
    data = [1, -2, 3, -4]
    expected = [1, -2, 3, -4]  # exact copy of input: 4 elements unchanged
    _observed(data, capsys)
    assert data == expected


def test_contract_single_argument():
    """Implement neg_nos(list1) takes one argument."""
    expected = 1  # neg_nos(list1) has 1 parameter
    assert len(inspect.signature(neg_nos).parameters) == expected
